row(13, 1, 'MATERIAL', f'ALL THE WORD THAT I COMMAND YOU, IT YOU SHALL KEEP TO DO; YOU SHALL NOT ADD TO IT NOR TAKE FROM IT. {HP(13, 1, (("את", "כל", "הדבר", "אשר", "אנכי", "מצוה", "אתכם"), "all the word that I command you — ONE seat; 4:2\'s plural clause its twin, seven tokens in order"), (("לא", "תסף", "עליו", "ולא", "תגרע", "ממנו"), "you shall not add to it nor take from it — the singular; 4:2 the plural, the only two"))} {AP(13, 1, (("לא", "תוספון", "עלוהי", "ולא", "תמנעון", "מניה"), "you shall not add to it nor WITHHOLD from it — take away made withhold"))} THE HEADER: the word\'s grain (82:5), the light as the weighty (82:1); the DB\'s 13:1 the English\'s 12:32 — no row of the shelf cites 12:32 (computed).')
row(13, 2, 'MATERIAL', f'WHEN A PROPHET ARISES AMONG YOU, OR A DREAMER OF A DREAM, AND GIVES YOU A SIGN OR A WONDER. {HP(13, 2, (("כי", "יקום", "בקרבך", "נביא"), "when a prophet arises among you — ONE seat; 18:15\'s \'from among you\' the true prophet\'s"), (("או", "חלם", "חלום"), "or a dreamer of a dream — the book\'s only dreamer, three seats in the chapter"), (("אות", "או", "מופת"), "a sign or a wonder — \'or\' the chapter\'s; the pair\'s twenty-five seats"))} {AP(13, 2, (("ויתן", "לך", "את", "או", "מופתא"), "and gives you a sign or a wonder — \'to you\' plain"))} THE FIRST CASE OPENS: the prophet\'s forms Moses\' (83:1), the dream not Moses\' channel (83:2); the closest verse in the Bible Jeroboam\'s sign at the altar (1 Kings 13:3 — computed).')
row(13, 3, 'MATERIAL', f'AND THE SIGN AND THE WONDER COME TO PASS OF WHICH HE SPOKE TO YOU, SAYING, LET US GO AFTER OTHER GODS WHICH YOU HAVE NOT KNOWN, AND LET US SERVE THEM. {HP(13, 3, (("ובא", "האות", "והמופת"), "and the sign and the wonder come to pass — ONE"), (("נלכה", "אחרי", "אלהים", "אחרים"), "let us go after other gods — THE SEDUCER\'S FORMULA, its first of three"), (("לא", "ידעתם", "ונעבדם"), "you have not known them, and let us serve them — the tagger reads \'you (sg.) knew THEM\'"))} {AP(13, 3, (("נהך", "בתר", "טעות", "עממיא"), "let us go after THE ERRORS OF THE PEOPLES — other gods the peoples\' errors"), (("די", "לא", "ידעתנון"), "which you knew them — the object suffix kept: Onkelos reads with the tagger"))} R. Yose the Galilean grants the sign true (84:1), R. Akiva makes the speaker a fallen prophet (84:2).')
row(13, 4, 'MATERIAL', f'YOU SHALL NOT HEARKEN TO THE WORDS OF THAT PROPHET OR TO THAT DREAMER OF THE DREAM, FOR THE LORD YOUR GOD IS TESTING YOU, TO KNOW WHETHER YOU LOVE THE LORD YOUR GOD WITH ALL YOUR HEART AND WITH ALL YOUR SOUL. {HP(13, 4, (("לא", "תשמע", "אל", "דברי", "הנביא", "ההוא"), "you shall not hearken to the words of that prophet — ONE; \'that prophet\' 18:20\'s"), (("כי", "מנסה", "יהוה", "אלהיכם", "אתכם"), "for the LORD your God is testing you — the verb\'s eight seats in the book, the participle here alone"), (("לדעת", "הישכם", "אהבים"), "to know whether you love — \'whether you are\' one seat; the participle \'who love the LORD\' one"))} {AP(13, 4, (("לא", "תקבל", "לפתגמי", "נביא", "ההוא"), "you shall not ACCEPT the words of that prophet — hear made accept, the chapter\'s four"), (("ארי", "מנסי", "יי", "אלהכון", "יתכון"), "for the LORD your God is testing you"))} THE MIXED VERSE — the singular \'you shall not hearken\' inside the plural test (the register); 11:13\'s plural \'heart and soul\' the closest kin (nine tokens in order — computed).')
row(13, 5, 'MATERIAL', f'AFTER THE LORD YOUR GOD YOU SHALL WALK, AND HIM YOU SHALL FEAR, AND HIS COMMANDMENTS YOU SHALL KEEP, AND HIS VOICE YOU SHALL OBEY, AND HIM YOU SHALL SERVE, AND TO HIM YOU SHALL CLEAVE. {HP(13, 5, (("אחרי", "יהוה", "אלהיכם", "תלכו"), "after the LORD your God you shall walk — ONE; the cloud (85:1)"), (("ובקלו", "תשמעו", "ואתו", "תעבדו", "ובו", "תדבקון"), "His voice obey, Him serve, to Him cleave — the paragogic nun; 10:20\'s four verbs the kin"))} {AP(13, 5, (("בתר", "דחלתא", "דיי", "אלהכון", "תהכון"), "after THE FEAR of the LORD your God you shall walk — the fear supplied"), (("ולמימריה", "תקבלון", "וקדמוהי", "תפלחון", "ובדחלתיה", "תתקרבון"), "His WORD accept, BEFORE Him serve, to His FEAR draw near — the Memra, the reverence, the fear"))} THE ONE PLURAL VERSE — six verbs, no object but Him; \'cleave\' seven in the book, the chapter\'s two (computed).')
row(13, 6, 'MATERIAL', f'AND THAT PROPHET OR THAT DREAMER OF THE DREAM SHALL BE PUT TO DEATH, FOR HE SPOKE REBELLION AGAINST THE LORD YOUR GOD WHO BROUGHT YOU OUT OF THE LAND OF EGYPT AND REDEEMED YOU FROM THE HOUSE OF BONDAGE, TO THRUST YOU FROM THE WAY WHICH THE LORD YOUR GOD COMMANDED YOU TO WALK IN; AND YOU SHALL PURGE THE EVIL FROM YOUR MIDST. {HP(13, 6, (("והנביא", "ההוא", "או", "חלם", "החלום", "ההוא", "יומת"), "that prophet or that dreamer shall be put to death — the chapter\'s one \'put to death\', its mode unsaid"), (("כי", "דבר", "סרה", "על", "יהוה"), "for he spoke rebellion against the LORD — the noun\'s two Torah seats (19:16 the false witness)"), (("והפדך", "מבית", "עבדים"), "and who redeemed you from the house of bondage — the participle\'s one seat in the Bible"), (("להדיחך", "מן", "הדרך"), "to thrust you from the way — the chapter\'s verb, three times"), (("ובערת", "הרע", "מקרבך"), "and you shall purge the evil from your midst — THE FORMULA\'S FIRST SEAT of nine"))} {AP(13, 6, (("יתקטל", "ארי", "מליל", "סטיא"), "shall be KILLED, for he spoke a FABRICATION — rebellion made a lie"), (("ותפלי", "עבד", "דביש", "מבינך"), "and remove the DOER of evil from among you — 86:10\'s reading in the Aramaic"))} The mode by analogy (86:6 stoning, R. Shimon strangling); the longest verse of the chapter (thirty-two tokens).')
row(13, 7, 'MATERIAL', f'WHEN YOUR BROTHER, THE SON OF YOUR MOTHER, OR YOUR SON OR YOUR DAUGHTER OR THE WIFE OF YOUR BOSOM OR YOUR FRIEND WHO IS AS YOUR OWN SOUL ENTICES YOU IN SECRET, SAYING, LET US GO AND SERVE OTHER GODS WHICH YOU HAVE NOT KNOWN, YOU NOR YOUR FATHERS. {HP(13, 7, (("כי", "יסיתך", "אחיך", "בן", "אמך"), "when your brother the son of your mother entices you — the verb\'s ONE Torah token"), (("או", "אשת", "חיקך", "או", "רעך", "אשר", "כנפשך"), "or the wife of your bosom or your friend as your own soul — one seat each; Jonathan\'s the kin"), (("בסתר", "לאמר", "נלכה", "ונעבדה"), "in secret, saying, let us go and serve — the formula\'s second"))} {AP(13, 7, (("ארי", "ימלכנך", "אחוך"), "when your brother COUNSELS you — entice made counsel"), (("אתת", "קימך"), "the wife of your COVENANT — the bosom made the covenant"))} THE SECOND CASE: the kin\'s inclusion table (87:4-11), the father in the last clause (87:11); the longest \'or\' chain (four).')
row(13, 8, 'MATERIAL', f'OF THE GODS OF THE PEOPLES ROUND ABOUT YOU, NEAR TO YOU OR FAR FROM YOU, FROM ONE END OF THE EARTH TO THE OTHER END OF THE EARTH. {HP(13, 8, (("מאלהי", "העמים", "אשר", "סביבתיכם"), "of the gods of the peoples round about you — 6:14\'s clause, spelled defective here"), (("מקצה", "הארץ", "ועד", "קצה", "הארץ"), "from one end of the earth to the other — 28:64\'s exile"))} {AP(13, 8, (("מטעות", "עממיא", "די", "בסחרניכון"), "of the errors of the peoples round about you"))} The headless piska\'s verse (88:1-2 — the near teach the far; the sun and the moon).')
row(13, 9, 'MATERIAL', f'YOU SHALL NOT CONSENT TO HIM NOR HEARKEN TO HIM, NOR SHALL YOUR EYE PITY HIM, NOR SHALL YOU SPARE NOR CONCEAL HIM. {HP(13, 9, (("לא", "תאבה", "לו", "ולא", "תשמע", "אליו"), "you shall not consent nor hearken — against love (89:1) and the enemy\'s help (89:2)"), (("ולא", "תחוס", "עינך", "עליו", "ולא", "תחמל"), "nor shall your eye pity him nor spare — the eye\'s clause the book\'s five, \'spare\' the Torah\'s two"), (("ולא", "תכסה", "עליו"), "nor conceal him — ONE"))} {AP(13, 9, (("לא", "תיבי", "ליה", "ולא", "תקבל", "מניה"), "you shall not consent to him nor ACCEPT from him"))} FIVE NEGATIONS IN ONE VERSE — the court\'s mercies suspended (89:4-7).')
row(13, 10, 'MATERIAL', f'BUT KILL, YOU SHALL KILL HIM; YOUR HAND SHALL BE ON HIM FIRST TO PUT HIM TO DEATH, AND THE HAND OF ALL THE PEOPLE AFTERWARD. {HP(13, 10, (("כי", "הרג", "תהרגנו"), "kill, you shall kill him — the infinitive absolute, ONE seat"), (("ידך", "תהיה", "בו", "בראשונה", "להמיתו"), "your hand shall be on him first to put him to death — 17:7\'s witnesses\' hand, seven tokens in order"), (("ויד", "כל", "העם", "באחרנה"), "and the hand of all the people afterward — the Torah\'s two seats, both this clause"))} {AP(13, 10, (("ידך", "תהי", "ביה", "בקדמיתא"), "your hand shall be on him first"))} The enticed\'s duty (89:8); the verdict irreversible (89:6-7).')
row(13, 11, 'MATERIAL', f'AND YOU SHALL STONE HIM WITH STONES THAT HE DIE, FOR HE SOUGHT TO THRUST YOU FROM THE LORD YOUR GOD WHO BROUGHT YOU OUT OF THE LAND OF EGYPT, OUT OF THE HOUSE OF BONDAGE. {HP(13, 11, (("וסקלתו", "באבנים", "ומת"), "and you shall stone him with stones that he die — Deuteronomy\'s verb of stoning (Leviticus\'s another)"), (("כי", "בקש", "להדיחך", "מעל", "יהוה"), "for he sought to thrust you from the LORD"), (("המוציאך", "מארץ", "מצרים", "מבית", "עבדים"), "who brought you out of the land of Egypt, out of the house of bondage — 5:6\'s preamble, six tokens"))} {AP(13, 11, (("ותרגמניה", "באבניא", "וימות"), "and you shall stone him with stones and he dies"), (("מדחלתא", "דיי"), "from THE FEAR of the LORD — the fear supplied a third time"))} The stones and the stone (90:1); the Decalogue\'s opening at the inciter\'s death.')
row(13, 12, 'MATERIAL', f'AND ALL ISRAEL SHALL HEAR AND FEAR, AND SHALL NOT DO AGAIN SUCH AN EVIL THING AS THIS IN YOUR MIDST. {HP(13, 12, (("וכל", "ישראל", "ישמעו", "ויראון"), "and all Israel shall hear and fear — THE FORMULA\'S FIRST of four, the one with the nun; Israel named once"), (("ולא", "יוספו", "לעשות", "כדבר", "הרע", "הזה"), "and shall not do again such an evil thing — \'add\' the header\'s root at the deed"))} {AP(13, 12, (("ישמעון", "וידחלון"), "shall hear and fear"))} The festival\'s execution disputed (91:1-2); the fifteen utterances (91:3), the eight honors not capital (91:4).')
row(13, 13, 'MATERIAL', f'WHEN YOU HEAR IN ONE OF YOUR CITIES WHICH THE LORD YOUR GOD GIVES YOU TO DWELL THERE, SAYING. {HP(13, 13, (("כי", "תשמע", "באחת", "עריך"), "when you hear in one of your cities — THE NUMBER VERSE [1]; one at a time (92:3)"), (("לשבת", "שם", "לאמר"), "to dwell there, saying — \'to dwell there\' the Torah\'s one seat; Jerusalem excluded (92:5)"))} {AP(13, 13, (("בחד", "מקרויך"), "in one of your cities"))} THE THIRD CASE OPENS — the report received, not sought (92:1).')
row(13, 14, 'MATERIAL', f'MEN, SONS OF BELIAL, HAVE GONE OUT FROM YOUR MIDST AND HAVE DRAWN AWAY THE INHABITANTS OF THEIR CITY, SAYING, LET US GO AND SERVE OTHER GODS WHICH YOU HAVE NOT KNOWN. {HP(13, 14, (("יצאו", "אנשים", "בני", "בליעל", "מקרבך"), "men, sons of Belial, have gone out from your midst — Belial\'s two Torah seats; Naboth\'s witnesses the closest verse"), (("וידיחו", "את", "ישבי", "עירם"), "and have drawn away the inhabitants of their city — THE ONE NARRATIVE VERB, inside the case"), (("אשר", "לא", "ידעתם"), "which you (pl.) have not known — the tagger\'s plural here, the singular-with-object at 13:3"))} {AP(13, 14, (("בני", "רשעא"), "sons of WICKEDNESS — Belial glossed"), (("ואטעיו", "ית", "יתבי", "קרתהון"), "and led astray the inhabitants of their city"), (("די", "לא", "ידעתון"), "which you (pl.) knew — the plural kept"))} Two men at least, adult, of the city itself (93:1-4); the speech the warning (93:5).')
row(13, 15, 'MATERIAL', f'THEN YOU SHALL INQUIRE AND SEARCH AND ASK DILIGENTLY; AND BEHOLD, IF IT IS TRUE, THE THING CERTAIN, THAT THIS ABOMINATION WAS DONE IN YOUR MIDST. {HP(13, 15, (("ודרשת", "וחקרת", "ושאלת", "היטב"), "and you shall inquire and search and ask diligently — three verbs; \'diligently\' an infinitive absolute, five seats"), (("והנה", "אמת", "נכון", "הדבר"), "and behold it is true, the thing certain — 17:4\'s twin, nine tokens in order"), (("נעשתה", "התועבה", "הזאת", "בקרבך"), "this abomination was done in your midst — 17:4 says \'in Israel\'"))} {AP(13, 15, (("ותתבע", "ותבדוק", "ותשאל", "יאות"), "and you shall seek and examine and ask WELL — \'well\' at all five seats of the Hebrew\'s word"))} THE SEVEN INQUIRIES from the word\'s analogy (93:6), the probes from the second clause (93:7-9).')
row(13, 16, 'MATERIAL', f'SMITE, YOU SHALL SMITE THE INHABITANTS OF THAT CITY WITH THE EDGE OF THE SWORD, DEVOTING IT AND ALL THAT IS IN IT AND ITS CATTLE WITH THE EDGE OF THE SWORD. {HP(13, 16, (("הכה", "תכה", "את", "ישבי", "העיר", "ההוא"), "smite, you shall smite the inhabitants of that city — THE KETIV: the masculine written for the feminine city"), (("לפי", "חרב", "החרם", "אתה"), "with the edge of the sword, devoting it — the Torah\'s five \'edge of the sword\'; the ban\'s verb thirteen"), (("בהמתה", "לפי", "חרב"), "its cattle with the edge of the sword — Jericho\'s and Amalek\'s cattle the run\'s kin"))} {AP(13, 16, (("קרתא", "ההיא", "לפתגם", "דחרב"), "that city (the FEMININE read) by the WORD of the sword"), (("גמר", "יתה"), "FINISH it — devote made finish"))} The children disputed, the caravan saves, the sword\'s manner (94:3); the righteous\' property (94:4-5).')
row(13, 17, 'MATERIAL', f'AND ALL ITS SPOIL YOU SHALL GATHER INTO THE MIDST OF ITS STREET, AND BURN WITH FIRE THE CITY AND ALL ITS SPOIL WHOLLY TO THE LORD YOUR GOD; AND IT SHALL BE A HEAP FOREVER, IT SHALL NOT BE BUILT AGAIN. {HP(13, 17, (("ואת", "כל", "שללה", "תקבץ", "אל", "תוך", "רחבה"), "and all its spoil you shall gather into the midst of its street — \'its street\' the Torah\'s one"), (("כליל", "ליהוה", "אלהיך"), "wholly to the LORD your God — Samuel\'s lamb the one kin; the priest\'s meal offering\'s word"), (("והיתה", "תל", "עולם", "לא", "תבנה", "עוד"), "and it shall be a heap forever, not built again — Ai\'s heap (Joshua 8:28), Tyre\'s \'not built\'"))} {AP(13, 17, (("גמיר", "קדם", "יי", "אלהך"), "FINISHED BEFORE the LORD your God — \'to\' made \'before\'"), (("ותהי", "תל", "חריב", "לעלם"), "and it shall be a RUINED mound forever — one seat in the book"))} Heaven\'s spoil excepted (95:4-5); Jericho\'s oath the run\'s case (95:6-7); not even a garden (96:1).')
row(13, 18, 'MATERIAL', f'AND NOTHING OF THE DEVOTED THING SHALL CLEAVE TO YOUR HAND, THAT THE LORD MAY TURN FROM THE FIERCENESS OF HIS ANGER AND GIVE YOU MERCY, AND HAVE MERCY ON YOU AND MULTIPLY YOU, AS HE SWORE TO YOUR FATHERS. {HP(13, 18, (("ולא", "ידבק", "בידך", "מאומה", "מן", "החרם"), "and nothing of the devoted thing shall cleave to your hand — Achan\'s \'of the devoted thing\'"), (("למען", "ישוב", "יהוה", "מחרון", "אפו"), "that the LORD may turn from the fierceness of His anger — Achan\'s valley says it back"), (("ונתן", "לך", "רחמים", "ורחמך", "והרבך"), "and give you mercy and have mercy on you and multiply you — Jacob\'s word for the brothers"), (("כאשר", "נשבע", "לאבתיך"), "as He swore to your fathers — the oath\'s AS_WHEN form, 13:18 and 19:8"))} {AP(13, 18, (("כמא", "די", "קיים", "לאבהתך"), "as He ESTABLISHED to your fathers — swore made established, the book\'s twenty-three"))} The benefit to the Salt Sea (96:2); the anger keyed to idolatry (96:3); the mercy two-armed (96:4); the fathers\' merit (96:5).')
row(13, 19, 'MATERIAL', f'WHEN YOU HEARKEN TO THE VOICE OF THE LORD YOUR GOD, TO KEEP ALL HIS COMMANDMENTS WHICH I COMMAND YOU TODAY, TO DO THE RIGHT IN THE EYES OF THE LORD YOUR GOD. {HP(13, 19, (("כי", "תשמע", "בקול", "יהוה", "אלהיך"), "when you hearken to the voice of the LORD your God — 28:1\'s and 28:15\'s opening, fourteen tokens"), (("לעשות", "הישר", "בעיני", "יהוה", "אלהיך"), "to do the right in the eyes of the LORD your God — Jehoshaphat\'s measure, three in the Bible"))} {AP(13, 19, (("ארי", "תקבל", "למימרא", "דיי", "אלהך"), "when you ACCEPT the WORD of the LORD your God — the Memra"), (("למעבד", "דכשר", "קדם", "יי", "אלהך"), "to do what is FIT before the LORD — 12:25\'s and 12:28\'s word"))} THE FOOTER — the header\'s sentence again (96:7), the right Heaven\'s (96:8); Moses\' second \'I\'.')

